+                } else {
+                    json!({"prompt": "hello", "logprobs": 0})
+                };
+                body["stream"] = json!(stream);
+                body["stream_options"] = if stream {
+                    json!({"include_usage": true})
+                } else {
+                    json!(null)
+                };
+                body["return_token_ids"] = json!(true);
